const PROPERTY = { title:'Title', url:'URL', category:'Category', summary:'Summary', source:'Source', publishedAt:'PublishedAt' }
type NewsItem = { title, url, category, summary, source, publishedAt }
type NewsResult = { ok:true, items:NewsItem[] } | { ok:false, reason:'missing-env'|'not-connected'|'unauthorized'|'unknown' }
function readTitle(properties, key) { const p = properties[key]; if (p?.type !== 'title') return ''; return p.title.map(t=>t.plain_text).join('').trim() }
// readRichText/readUrl/readSelectName/readDateStart도 동일하게 property?.type 판별 유니온으로 좁힌다

pseudocode:
const notion = new Client({ auth: process.env.NOTION_TOKEN })
function toNewsItem(page): NewsItem | null { const title=readTitle(...); const url=readUrl(...); if(!title||!url) return null; return {...} }
async function getNewsItems(): Promise<NewsResult> {
  if (!process.env.NOTION_TOKEN || !process.env.NOTION_DATABASE_ID) return {ok:false, reason:'missing-env'}
  try {
    const db = await notion.databases.retrieve({database_id: process.env.NOTION_DATABASE_ID})
    const dataSourceId = db.data_sources[0].id  // 실제 SDK .d.ts 타입명 확인 필요, 다르면 notion.request<{...}>()로 제네릭 명시
    const res = await notion.dataSources.query({data_source_id: dataSourceId})
    const items = res.results.filter(isFullPage).map(toNewsItem).filter(Boolean)
    return {ok:true, items}
  } catch (e) {
    if (isNotionClientError(e) && e.code === APIErrorCode.ObjectNotFound) return {ok:false, reason:'not-connected'}
    if (isNotionClientError(e) && e.code === APIErrorCode.Unauthorized) return {ok:false, reason:'unauthorized'}
    return {ok:false, reason:'unknown'}
  }
}

