export async function NewsBoard({ category }: { category?: string }) {
  const result = await getNewsItems()
  if (!result.ok) return <ErrorCard reason={result.reason} />  // 다음 태스크에서 구현
  const items = category ? result.items.filter(i=>i.category===category) : result.items
  if (items.length === 0) return <EmptyState category={category} />  // 다음 태스크
  return <>
    <CategoryTabs active={category} />  {/* Badge render={<Link .../>} 6개, /news?category=... */}
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {items.map(item => <Card className="h-full"><Link href={item.url} target="_blank" rel="noopener noreferrer">...</Link></Card>)}
    </div>
  </>
}

