function ErrorCard({ reason }) {
  const MESSAGES = {
    'missing-env': '.env.local을 만들고 NOTION_TOKEN/NOTION_DATABASE_ID를 채운 뒤 개발 서버를 재시작하세요',
    'not-connected': 'Notion에서 ⋯ → 연결 → integration을 선택하세요 (대부분 이 단계가 빠졌습니다)',
    'unauthorized': 'my-integrations에서 Secret을 다시 복사해 .env.local에 붙여넣고 재시작하세요',
    'unknown': '터미널의 에러 로그를 확인하세요',
  }
  return <Card><TriangleAlert/>{MESSAGES[reason]}</Card>
}
function EmptyState({ category }) {
  return category
    ? <Card><Inbox/>{`'${category}' 카테고리에 아직 뉴스가 없어요`}<Button render={<Link href="/news"/>}>전체 보기</Button></Card>
    : <Card><Inbox/>Notion에 행을 추가하고 Title, URL, Category를 채운 뒤 새로고침하세요</Card>
}

